function DetailTabs({items}:{items:{name:string;content:React.ReactNode}[]}){return <Tabs defaultValue={items[0].name} className="detail-tabs"><div className="tab-scroller"><TabsList>{items.map(i=><TabsTrigger key={i.name} value={i.name}>{i.name}</TabsTrigger>)}</TabsList></div>{items.map(i=><TabsContent key={i.name} value={i.name}>{i.content}</TabsContent>)}</Tabs>}
function Info({items}:{items:[string,React.ReactNode][]}){return <dl className="info-grid">{items.map(([a,b])=><div key={a}><dt>{a}</dt><dd>{b}</dd></div>)}</dl>}
export function ProgramDetail({id}:{id:string}){const s=useNexus(),v=useVisible(),p=s.programs.find(x=>x.id===id);const [edit,setEdit]=useState(false),[draft,setDraft]=useState(p?.draft??p?.curriculum??'');if(!p)return <NoResults/>;const materials=v.files.filter(f=>f.program===id);return <><Back to="programs"/><div className="glass detail-hero"><ProgramMark program={p}/><div><Badge tone={p.color}>{p.type}</Badge><h1>{p.name}</h1><p>{p.en}</p></div><div className="actions"><Badge tone="green">{p.status}</Badge><button className="secondary" onClick={()=>s.go('programs/'+id+'/article')}><BookOpen size={16}/>项目书</button><button className="secondary" onClick={()=>s.go('articles?program='+id)}><FileText size={16}/>项目推文</button>{s.role!=='sales'&&<button className="secondary" onClick={()=>s.go('programs/'+id+'/compose')}><FileText size={16}/>编辑项目书</button>}</div></div><ProgramOfferSummary program={id}/><DetailTabs items={[{name:'开班队伍',content:<CohortGrid program={id}/>},{name:'项目概览',content:<div className="detail-grid"><section className="glass panel prose"><h2>关于项目</h2><p>{p.description}</p><p>通过导师指导与团队实践，建立问题分析、协作与成果表达能力。正式安排以项目公告为准。</p><Info items={[["适合学生",'对相关领域感兴趣的高中生'],['授课形式','线上小班 · 导师指导'],['核心目标','探索问题、协作实践、展示成果'],['最近时间节点',p.date]]}/></section><section className="glass panel"><h2>快速访问</h2><div className="stack-list">{materials.map(f=><ResourceItem key={f.id} file={f}/>)}{!materials.length&&<p className="muted">资料正在准备中</p>}</div></section></div>},{name:'招生资料',content:<section className="glass panel"><SectionTitle title="项目资料" sub="已授权的资料可在线预览或下载"/>{materials.map(f=><ResourceItem key={f.id} file={f}/>)}{!materials.length&&<NoResults/>}</section>},{name:'课程安排',content:<section className="glass panel prose"><SectionTitle title="课程结构" action={s.role!=='sales'?'编辑课程':undefined} onClick={()=>setEdit(!edit)}/>{edit?<div className="form-stack"><FormField label="课程内容（每行一个主题）"><textarea value={draft} onChange={e=>setDraft(e.target.value)} rows={7}/></FormField><div className="actions"><button className="secondary" onClick={()=>{s.setPrograms(ps=>ps.map(x=>x.id===id?{...x,draft}:x));s.log('保存课程草稿：'+p.name);toast.success('草稿已保存，仅运营可见')}}>保存草稿</button><button className="primary" onClick={()=>{if(!draft.trim())return toast.error('请填写课程内容');s.setPrograms(ps=>ps.map(x=>x.id===id?{...x,curriculum:draft,draft:undefined,published:true}:x));setEdit(false);s.log('发布课程安排：'+p.name);toast.success('课程已发布，销售端可查看')}}>发布更新</button></div></div>:p.published?<ol className="curriculum">{p.curriculum.split('\n').map((x,i)=><li key={i}><span>{String(i+1).padStart(2,'0')}</span><div><h3>{x}</h3><p>导师引导 · 团队实践 · 阶段成果</p></div></li>)}</ol>:<Notice>课程尚未发布，请关注项目公告。</Notice>}{!edit&&s.role!=='sales'&&p.draft&&<Notice>此项目有未发布草稿，销售端仍显示已发布版本。</Notice>}</section>},{name:'关键时间',content:<section className="glass panel"><h2>项目时间轴</h2><ol className="timeline">{['招生与报名','项目启动','课程与实践','成果提交','项目结项'].map((x,i)=><li key={x}><span className={i===0?'current':''}/><div><h3>{x}</h3><p>{i===0?p.date:'具体时间待运营发布'}</p></div></li>)}</ol></section>},{name:'常见问题',content:<section className="glass panel prose">{[['项目适合哪些学生？','适合对项目领域有兴趣，希望提升研究、协作与表达能力的高中生。具体资格以正式招生文件为准。'],['如何安排课程？','请查看已发布的课程安排。老师会在项目开始前确认队伍排期。'],['在哪里查看项目成果要求？','成果要求由运营老师在项目课程和资料区发布。'],['如何报名及了解费用？','请联系负责顾问确认正式报名条件、费用和协议。']].map(([q,a])=><details className="faq" key={q}><summary>{q}</summary><p>{a}</p></details>)}</section>} ]}/></>}
const healthTone=(h:string)=>h==='状态不佳'?'poor':h==='需关注'?'watch':'good';
const shortStamp=()=>{const d=new Date(),pad=(n:number)=>String(n).padStart(2,'0');return `${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`};
function HealthSelect({student}:{student:Student}){const s=useNexus();return <Select value={student.health} onValueChange={v=>{const h=v as StudentHealth;s.setStudents(a=>a.map(i=>i.id===student.id?{...i,health:h,healthUpdated:shortStamp(),healthBy:s.user?.name||''}:i));s.log(`${student.name} 的学生状态更新为 ${h}`);toast.success(`${student.name}：${h}`)}}><SelectTrigger className={'choice health-choice '+healthTone(student.health)} aria-label={`设置${student.name}的学生状态`}><SelectValue/></SelectTrigger><SelectContent>{healthLevels.map(h=><SelectItem key={h} value={h}>{h}</SelectItem>)}</SelectContent></Select>}
function WorkCell({list}:{list:Assignment[]}){const w=assignmentSummary(list);return <span className="work-cell"><span><b>{w.submitted}</b>/{w.total} 已交</span><small className={w.overdue?'poor':w.revise?'watch':''}>{w.overdue?`逾期 ${w.overdue}`:''}{w.overdue&&w.revise?' · ':''}{w.revise?`需修改 ${w.revise}`:''}{!w.overdue&&!w.revise?(w.average!=null?`均分 ${w.average}`:'暂无批改'):''}</small></span>}
export function Students(){const s=useNexus();return s.role==='sales'?<StudentWorkspace/>:<OpsStudents/>}
function OpsStudents(){const s=useNexus(),v=useVisible();const [open,setOpen]=useState<string|null>(null);
  const count=(h:StudentHealth)=>v.students.filter(x=>x.health===h).length;
  const slices=useMemo(()=>{const m=new Map<string,number>();for(const x of v.students)m.set(x.program||'',(m.get(x.program||'')||0)+1);return [...m.entries()].map(([id,value])=>{const p=s.programs.find(p=>p.id===id);return {id:id||'__none',label:p?.short||p?.name||'未分配项目',sub:p?.name,value}}).sort((a,b)=>b.value-a.value)},[v.students,s.programs]);
  const pick=slices.find(x=>x.id===open);const projectName=open==='__all'?'全部项目':s.programs.find(p=>p.id===open)?.name;
  return <><PageTitle title="学生管理" en="STUDENT WORKSPACE" description="关注每一个成长节点，与学生一起向前。" action="新增学生" onAction={()=>s.go('students/new')}/>
  <div className="mini-stats">{[['全部学生',v.students.length],['状态不佳',count('状态不佳')],['需关注',count('需关注')],['进行中',v.students.filter(x=>x.status==='进行中').length]].map(([a,b])=><div className="glass" key={a}><span>{a}</span><b>{b}</b></div>)}</div>
  <section className="glass panel pie-panel"><div className="section-title"><div><h2>项目学生分布</h2><span>按所属项目统计 · 点击扇区或图例查看该项目学生</span></div><button className="primary compact" onClick={()=>setOpen('__all')}><Users size={15}/>查看全部学生</button></div>
  {v.students.length?<StudentPie3D slices={slices} total={v.students.length} active={open&&open!=='__all'?open:null} onPick={setOpen}/>:<EmptyState icon={Users} title="还没有学生" description="新增第一位学生，或从项目报名开始建立学生档案。" action="新增学生" onAction={()=>s.go('students/new')}/>}</section>
  <Dialog open={!!open} onOpenChange={o=>!o&&setOpen(null)}><DialogContent className="project-students-dialog">{open&&<><div className="psd-head"><span className="psd-dot" style={{background:open==='__all'?'var(--nx-accent)':sliceColor(Math.max(0,slices.findIndex(x=>x.id===open)))}}/><div><DialogTitle>{open==='__all'?'全部学生':(pick?.sub||pick?.label)}</DialogTitle><DialogDescription>{open==='__all'?`共 ${v.students.length} 位学生 · 可按项目、状态筛选`:`${pick?.value??0} 位学生 · 占全部 ${((pick?.value??0)/(v.students.length||1)*100).toFixed(1)}%`}</DialogDescription></div></div>
  <StudentWorkspace embedded initialProject={open==='__none'?'全部项目':projectName||'全部项目'} noProgram={open==='__none'}/></>}</DialogContent></Dialog></>}
function StudentWorkspace({embedded=false,initialProject='全部项目',noProgram=false}:{embedded?:boolean;initialProject?:string;noProgram?:boolean}={}){const s=useNexus(),v=useVisible();const sales=s.role==='sales';const [q,setQ]=useState(''),[status,setStatus]=useState('全部状态'),[health,setHealth]=useState('全部学生状态'),[project,setProject]=useState(initialProject),[sheet,setSheet]=useState(false),[page,setPage]=useState(1),[pageSize,setPageSize]=useState(10);
  const filtered=v.students.filter(x=>(!noProgram||!s.programs.some(p=>p.id===x.program))&&(x.name+x.id).toLowerCase().includes(q.toLowerCase())&&(status==='全部状态'||x.status===status)&&(health==='全部学生状态'||x.health===health)&&(project==='全部项目'||s.programs.find(p=>p.id===x.program)?.name===project));
  // Sales see the students who need help first: 状态不佳 → 需关注 → 状态良好.
  const list=sales?sortByHealth(filtered,s.assignments):filtered;
  useEffect(()=>setPage(1),[q,status,project,health,pageSize]);const rows=list.slice((page-1)*pageSize,page*pageSize);const work=(id:string)=>s.assignments.filter(a=>a.student===id);
  const count=(h:StudentHealth)=>v.students.filter(x=>x.health===h).length;
  const filters=<><FormField label="学生状态"><Choice value={health} onChange={setHealth} options={['全部学生状态',...healthLevels]} label="学生状态"/></FormField><FormField label="所属项目"><Choice value={project} onChange={setProject} options={['全部项目',...s.programs.map(p=>p.name)]} label="所属项目"/></FormField><FormField label="项目状态"><Choice value={status} onChange={setStatus} options={['全部状态','待分配','待开课','进行中','暂停中','已结项','已退出']} label="项目状态"/></FormField></>;
  return <>{!embedded&&<><PageTitle title={sales?'我的学生':'学生管理'} en="STUDENT WORKSPACE" description={sales?'状态不佳的学生排在最前，优先跟进需要帮助的同学。':'关注每一个成长节点，与学生一起向前。'} action={!sales?'新增学生':undefined} onAction={()=>s.go('students/new')}/>
  {sales?<div className="mini-stats health-stats">{([['全部学生','全部学生状态',v.students.length,''],...healthLevels.map(h=>[h,h,count(h),healthTone(h)])] as [string,string,number,string][]).map(([label,value,n,tone])=><button type="button" className={'glass health-stat '+tone+(health===value?' selected':'')} aria-pressed={health===value} key={label} onClick={()=>setHealth(value)}><span>{tone&&<i aria-hidden="true"/>}{label}</span><b>{n}</b></button>)}</div>
  :<div className="mini-stats">{[['全部学生',v.students.length],['状态不佳',count('状态不佳')],['需关注',count('需关注')],['进行中',v.students.filter(x=>x.status==='进行中').length]].map(([a,b])=><div className="glass" key={a}><span>{a}</span><b>{b}</b></div>)}</div>}</>}
  <div className={embedded?'psd-body':'glass panel'}><div className="filter-toolbar"><SearchBox value={q} onChange={setQ} placeholder="搜索学生姓名或编号"/><div className="desktop-filters">{filters}</div><button className="secondary mobile-filter" onClick={()=>setSheet(true)}><SlidersHorizontal size={18}/>筛选</button></div>
  <div className="results-meta">{list.length} 位学生 <span>{sales?'按学生状态排序：状态不佳 → 需关注 → 状态良好':'学生状态由运营老师维护 · 销售端据此排序'}</span></div>
  <div className="desktop-table"><Table className="student-table"><TableHeader><TableRow>{['学生','学生状态','所属项目','作业提交','项目状态','最近更新',''].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map(x=><TableRow key={x.id} className={'student-row '+healthTone(x.health)} onClick={e=>{if(!(e.target as HTMLElement).closest('button,a,[role=combobox],[role=option],[role=listbox]'))s.go('students/'+x.id)}}><TableCell><button className="student-name" onClick={()=>s.go('students/'+x.id)}><span className="avatar">{x.name.slice(0,1)}</span><span>{x.name}<small>{x.id}</small></span></button></TableCell><TableCell>{sales?<HealthBadge value={x.health} title/>:<HealthSelect student={x}/>}</TableCell><TableCell>{s.programs.find(p=>p.id===x.program)?.short}<small className="cell-sub">{s.teams.find(t=>t.id===x.team)?.name||'待分配'}</small></TableCell><TableCell><WorkCell list={work(x.id)}/></TableCell><TableCell><Badge tone={x.status==='进行中'?'green':'violet'}>{x.status}</Badge></TableCell><TableCell>{x.updated}</TableCell><TableCell><button className="icon-button" aria-label={`查看${x.name}`} onClick={()=>s.go('students/'+x.id)}><ChevronRight size={17}/></button></TableCell></TableRow>)}</TableBody></Table></div>
  <div className="student-cards">{rows.map(x=><button className="student-card" key={x.id} onClick={()=>s.go('students/'+x.id)}><div className="card-top"><div className="student-name"><span className="avatar">{x.name.slice(0,1)}</span><span>{x.name}<small>{x.id}</small></span></div><HealthBadge value={x.health}/></div><Info items={[["项目",s.programs.find(p=>p.id===x.program)?.name],["作业",<WorkCell key="w" list={work(x.id)}/>],["项目状态",x.status]]}/><div className="card-bottom"><span>更新于 {x.updated}</span><ChevronRight size={16}/></div></button>)}</div>
  {!list.length&&(v.students.length?<NoResults/>:sales?<EmptyState icon={Users} title="暂无负责的学生" description="运营老师为学生指定负责销售后，学生会出现在这里。"/>:<EmptyState icon={Users} title="还没有学生" description="新增第一位学生，或从项目报名开始建立学生档案。" action="新增学生" onAction={()=>s.go('students/new')}/>)}{list.length>0&&<PremiumPager page={page} pageSize={pageSize} total={list.length} onPage={setPage} onPageSize={n=>{setPageSize(n);setPage(1)}}/>}</div>
  <Sheet open={sheet} onOpenChange={setSheet}><SheetContent side="bottom" className="bottom-sheet"><SheetHeader><SheetTitle>筛选学生</SheetTitle><SheetDescription>按学生状态、项目与参与状态快速查找</SheetDescription></SheetHeader><div className="form-stack">{filters}<div className="actions"><button className="secondary" onClick={()=>{setProject('全部项目');setStatus('全部状态');setHealth('全部学生状态')}}>重置</button><button className="primary" onClick={()=>setSheet(false)}>查看 {list.length} 位学生</button></div></div></SheetContent></Sheet></>}
function StudentStatusPanel({student:x}:{student:Student}){const s=useNexus();const ops=s.role!=='sales'&&s.role!=='teacher';const [level,setLevel]=useState<StudentHealth>(x.health),[note,setNote]=useState(x.healthNote);const w=assignmentSummary(s.assignments.filter(a=>a.student===x.id));const changed=level!==x.health||note.trim()!==x.healthNote;
  const save=()=>{s.setStudents(a=>a.map(i=>i.id===x.id?{...i,health:level,healthNote:note.trim(),healthUpdated:shortStamp(),healthBy:s.user?.name||'',updated:'刚刚'}:i));s.log(`${x.name} 的学生状态更新为 ${level}`);toast.success('学生状态已更新，销售端列表将按新状态排序')};
  return <section className={'glass panel student-status-panel '+healthTone(x.health)}><div className="status-summary"><div className="status-current"><span className="status-label">学生状态</span><HealthBadge value={x.health}/><p>{x.healthNote||healthHints[x.health]}</p>{x.healthBy&&<small>由 {x.healthBy} 更新于 {x.healthUpdated}</small>}</div>
  <dl className="work-metrics"><div><dt>作业提交率</dt><dd>{w.rate}<small>%</small></dd></div><div><dt>已批改</dt><dd>{w.reviewed}<small> 份</small></dd></div><div className={w.overdue?'poor':''}><dt>逾期未交</dt><dd>{w.overdue}<small> 份</small></dd></div><div className={w.revise?'watch':''}><dt>需修改</dt><dd>{w.revise}<small> 份</small></dd></div><div><dt>平均分</dt><dd>{w.average??'—'}</dd></div></dl></div>
  {ops&&<div className="status-editor"><span className="status-label">更新学生状态 · 销售端按此排序，状态不佳的学生排在最前</span><div className="status-options" role="radiogroup" aria-label="学生状态">{healthLevels.map(h=><button type="button" key={h} role="radio" aria-checked={level===h} className={'status-option '+healthTone(h)+(level===h?' selected':'')} onClick={()=>setLevel(h)}><HealthBadge value={h}/><small>{healthHints[h]}</small></button>)}</div><FormField label="状态说明（对负责销售可见）"><textarea rows={2} maxLength={120} value={note} placeholder="例如：连续两次作业逾期，已约家长沟通" onChange={e=>setNote(e.target.value)}/></FormField><button className="primary self-start" disabled={!changed} onClick={save}>保存学生状态</button></div>}
  </section>}
const assignmentTone=(st:string)=>st==='逾期未交'?'poor':st==='需修改'?'watch':st==='已批改'?'good':st==='已提交'?'info':'neutral';
function AssignmentList({id}:{id:string}){const s=useNexus();const list=s.assignments.filter(a=>a.student===id).slice().sort((a,b)=>b.due.localeCompare(a.due));return <section className="glass panel"><SectionTitle title="作业提交与老师反馈" sub="按截止时间倒序"/>{list.map(a=><article key={a.id} className="assignment-row"><span className={'assignment-state '+assignmentTone(a.status)}>{a.status}</span><div className="assignment-main"><h3>{a.title}</h3><p>{s.programs.find(p=>p.id===a.program)?.short} · 截止 {a.due} · {a.submitted?`提交于 ${a.submitted}`:'尚未提交'} · {a.teacher}</p>{a.feedback&&<blockquote>{a.feedback}</blockquote>}</div><div className="assignment-score">{a.score!=null?<><b>{a.score}</b><small>分</small></>:<small>—</small>}</div></article>)}{!list.length&&<NoResults/>}</section>}
export function StudentDetail({id}:{id:string}){const s=useNexus(),v=useVisible(),x=v.students.find(x=>x.id===id);const enrollmentList=s.enrollments.filter(e=>e.student===id);const [activeEnrollment,setActiveEnrollment]=useState(enrollmentList[0]?.id??'');const active=enrollmentList.find(e=>e.id===activeEnrollment);const [status,setStatus]=useState(active?.status??x?.status??'进行中');if(!x)return <NoResults/>;const p=s.programs.find(p=>p.id===x.program)!,t=s.teams.find(t=>t.id===x.team),fs=v.feedbacks.filter(f=>f.student===id);return <><Back to="students"/><div className="glass detail-hero"><span className="avatar large-avatar">{x.name.slice(0,1)}</span><div><h1>{x.name}</h1><p>{x.id} · {x.grade}</p></div><div className="actions"><HealthBadge value={x.health}/><Badge tone="green">{x.status}</Badge>{s.role!=='sales'&&<button className="secondary" onClick={()=>s.go('students/'+id+'/edit')}>编辑档案</button>}</div></div><StudentStatusPanel key={x.health+x.healthNote} student={x}/><DetailTabs items={[{name:'作业与反馈',content:<AssignmentList id={id}/>},{name:'基本档案',content:<section className="glass panel prose"><Info items={profileInfoItems(x)}/><p className="muted">花名册字段来自各项目导入的并集；空值已省略，后续可再精简展示列。</p><h2>当前项目参与状态</h2><p>{active?s.programs.find(p=>p.id===active.program)?.name:p.name}</p>{enrollmentList.length>1&&<Choice label="选择参与项目" value={s.programs.find(p=>p.id===active?.program)?.name||p.name} onChange={name=>{const e=enrollmentList.find(e=>s.programs.find(p=>p.id===e.program)?.name===name)!;setActiveEnrollment(e.id);setStatus(e.status)}} options={enrollmentList.map(e=>s.programs.find(p=>p.id===e.program)!.name)}/>}<p className="muted">各项目的参与状态独立保存。</p>{s.role!=='sales'?<div className="actions"><Choice label="更新项目状态" value={status} onChange={setStatus} options={['待分配','待开课','进行中','暂停中','已结项','已退出']}/><button className="primary" onClick={()=>{s.setEnrollments(a=>a.map(e=>e.id===activeEnrollment?{...e,status}:e));if(active?.program===x.program)s.setStudents(a=>a.map(i=>i.id===id?{...i,status,updated:'刚刚'}:i));s.log(`${x.name} 的项目状态更新为 ${status}`);toast.success('项目状态已更新')}}>保存状态</button></div>:<Badge>{active?.status??x.status}</Badge>}</section>},{name:'项目记录',content:<section className="glass panel">{enrollmentList.map(e=>{const ep=s.programs.find(p=>p.id===e.program)!;return <button key={e.id} className="record-link" onClick={()=>s.go('programs/'+ep.id)}><ProgramMark program={ep}/><div><h2>{ep.name}</h2><p>{e.status} · {s.teams.find(t=>t.id===e.team)?.name||'待分配'}</p></div><ChevronRight/></button>})}<Notice>项目参与状态独立于学生档案状态管理。</Notice>{s.role!=='sales'&&<button className="secondary" onClick={()=>s.go('students/'+id+'/enroll')}>关联新项目</button>}</section>},{name:'队伍信息',content:<section className="glass panel">{t?<><Info items={[["队伍名称",t.name],["指导老师",t.teacher],["当前阶段",t.stage>0?stages[t.stage-1]:'未设定'],["成员人数",s.students.filter(a=>s.enrollments.some(e=>e.student===a.id&&e.team===t.id)).length+' 人']]}/>{t.stage>0&&<StageBar stage={t.stage}/>}<button className="secondary" onClick={()=>s.go('teams/'+t.id)}>查看队伍详情</button></>:<NoResults/>}</section>},{name:'课程记录',content:<section className="glass panel">{v.courses.filter(c=>enrollmentList.some(e=>e.team===c.team)).map(c=><CourseRow key={c.id} id={c.id}/>)}</section>},{name:'教学反馈',content:<section className="glass panel">{fs.length?fs.map(f=><article className="feedback-card" key={f.id}><div className="card-top"><Badge tone="green">{f.visible?'销售可见':'仅运营可见'}</Badge><small>{f.date}</small></div><h3>学习表现与本次进展</h3><p>{f.content}</p><h3>下一步安排</h3><p>{f.next}</p></article>):<NoResults/>}</section>},{name:'重要节点',content:<section className="glass panel prose"><h2>{p.name}</h2><p>下一个项目节点：{p.date}</p><button className="secondary" onClick={()=>s.go('programs/'+p.id)}>查看项目时间轴</button></section>} ]}/></>}
export function Teams(){const s=useNexus(),v=useVisible();const [q,setQ]=useState(''),[filter,setFilter]=useState(s.route.includes('attention')?'需要关注':'全部队伍'),[program,setProgram]=useState('');const programChips=s.programs.map(p=>({id:p.id,name:p.name,count:v.teams.filter(t=>t.program===p.id).length})).filter(p=>p.count>0);const list=v.teams.filter(t=>(t.name+s.programs.find(p=>p.id===t.program)?.name).includes(q)&&(!program||t.program===program)&&(filter==='全部队伍'||(filter==='需要关注'?t.status!=='正常进行':t.status==='正常进行')));return <><PageTitle title="队伍管理" en="TEAM MANAGEMENT" description="协同每一支队伍，让想法走向成果。" action={s.role!=='sales'?'新建队伍':undefined} onAction={()=>s.go('teams/new')}/><div className="filter-toolbar"><SearchBox value={q} onChange={setQ} placeholder="搜索队伍或项目"/><Choice value={filter} onChange={setFilter} options={['全部队伍','需要关注','正常进行']} label="队伍状态"/></div>{programChips.length>0&&<div className="filter-chips team-program-chips" role="group" aria-label="按项目筛选队伍"><button type="button" className={!program?'selected':''} aria-pressed={!program} onClick={()=>setProgram('')}>全部<em>{v.teams.length}</em></button>{programChips.map(p=><button type="button" key={p.id} className={program===p.id?'selected':''} aria-pressed={program===p.id} onClick={()=>setProgram(x=>x===p.id?'':p.id)}>{p.name}<em>{p.count}</em></button>)}</div>}<div className="results-meta">共 {list.length} 支队伍</div><div className="team-grid">{list.map(t=><button key={t.id} className="glass team-card" onClick={()=>s.go('teams/'+t.id)}><div className="card-top"><ProgramMark program={s.programs.find(p=>p.id===t.program)!} small/><Badge tone={t.status==='正常进行'?'green':'orange'}>{t.status}</Badge></div><h2>{t.name}</h2><p>{s.programs.find(p=>p.id===t.program)?.name}</p><div className="stage-heading"><span>{t.stage>0?stages[t.stage-1]:'阶段未设定'}</span><b>{t.stage>0?`0${t.stage} / 05`:'—'}</b></div>{t.stage>0?<StageBar stage={t.stage}/>:<div className="meter" aria-hidden="true"/>}<div className="card-bottom"><span><Users size={15}/>{s.students.filter(x=>s.enrollments.some(e=>e.student===x.id&&e.team===t.id)).length} 位成员</span><span>{t.teacher}<ChevronRight size={16}/></span></div></button>)}</div>{!list.length&&(v.teams.length?<NoResults/>:<EmptyState icon={Users} title="还没有队伍" description="新建队伍并关联项目，之后可为学生分配队伍、跟进阶段进度。" action={s.role!=='sales'?'新建队伍':undefined} onAction={()=>s.go('teams/new')}/>)}</>}
export function TeamDetail({id}:{id:string}){const s=useNexus(),v=useVisible(),t=v.teams.find(t=>t.id===id);
  const teamCourses=v.courses.filter(c=>c.team===id);
  const logs=s.teamLogs.filter(l=>l.team===id).slice().sort((a,b)=>b.at.localeCompare(a.at));
  const leader=!!s.leader;
  const ops=s.role!=='sales';
  const [stagePick,setStagePick]=useState(t&&t.stage>0?stages[t.stage-1]:'');
  const [prog,setProg]=useState({summary:t?.progress?.summary||'',milestones:t?.progress?.milestones||'',risks:t?.progress?.risks||''});
  const [mats,setMats]=useState({checklist:t?.materials?.checklist||'',links:t?.materials?.links||'',notes:t?.materials?.notes||''});
  if(!t)return <NoResults/>;
  const stamp=()=>shortStamp();
  const appendLog=(action:string,detail:string)=>{const at=stamp();s.setTeamLogs(a=>[{id:'TL-'+Date.now().toString(36)+Math.random().toString(36).slice(2,6),team:id,at,by:s.user?.email||'',byName:s.user?.name||'系统',action,detail},...a]);s.log(`${t.name} · ${action}`)};
  const saveStage=()=>{if(!leader)return toast.error('仅部门负责人（项目经理）可设定项目阶段');if(!stagePick){s.setTeams(a=>a.map(x=>x.id===id?{...x,stage:0}:x));appendLog('清空项目阶段','等待项目经理后续设定');toast.success('项目阶段已清空');return}const n=stages.indexOf(stagePick)+1;s.setTeams(a=>a.map(x=>x.id===id?{...x,stage:n}:x));appendLog('设定项目阶段',stagePick);toast.success('项目阶段已更新')};
  const saveProgress=()=>{const progress={...prog,updated:stamp(),updatedBy:s.user?.name||''};s.setTeams(a=>a.map(x=>x.id===id?{...x,progress}:x));appendLog('更新队伍进度',prog.summary.slice(0,80)||'已保存进度字段');toast.success('队伍进度已保存')};
  const saveMaterials=()=>{const materials={...mats,updated:stamp(),updatedBy:s.user?.name||''};s.setTeams(a=>a.map(x=>x.id===id?{...x,materials}:x));appendLog('更新成果材料',mats.checklist.slice(0,80)||'已保存材料字段');toast.success('成果材料已保存')};
  const stageSection=<section className="glass panel team-progress"><SectionTitle title="项目阶段" sub={t.stage>0?`${stages[t.stage-1]} · 指导老师 ${t.teacher}`:`未设定 · 仅部门负责人（张捷嘉）可创建 · 指导老师 ${t.teacher}`}/>{t.stage>0?<><StageBar stage={t.stage}/><div className="stage-labels">{stages.map(x=><span key={x}>{x}</span>)}</div></>:<Notice>项目阶段暂未设定，可先为空；由项目经理稍后创建。</Notice>}{leader&&<div className="form-stack" style={{marginTop:16}}><FormField label="设定项目阶段（部门负责人）"><Choice value={stagePick||'（清空 / 未设定）'} onChange={v=>setStagePick(v==='（清空 / 未设定）'?'':v)} options={['（清空 / 未设定）',...stages]} label="项目阶段"/></FormField><button type="button" className="primary self-start" onClick={saveStage}>保存阶段</button></div>}</section>;
  const progressTab=<section className="glass panel form-stack"><SectionTitle title="队伍进度" sub="字段由项目经理定义；队伍老师 / 运营老师填写"/><FormField label="进度摘要"><textarea rows={4} value={prog.summary} disabled={!ops} onChange={e=>setProg(p=>({...p,summary:e.target.value}))} placeholder="本周完成情况、整体完成度…"/></FormField><FormField label="关键里程碑"><textarea rows={4} value={prog.milestones} disabled={!ops} onChange={e=>setProg(p=>({...p,milestones:e.target.value}))} placeholder="已完成 / 进行中的里程碑"/></FormField><FormField label="风险与阻塞"><textarea rows={3} value={prog.risks} disabled={!ops} onChange={e=>setProg(p=>({...p,risks:e.target.value}))} placeholder="需要协调的问题"/></FormField>{t.progress?.updated&&<p className="muted">最近由 {t.progress.updatedBy} 更新于 {t.progress.updated}</p>}{ops&&<button type="button" className="primary self-start" onClick={saveProgress}>保存队伍进度</button>}</section>;
  const materialsTab=<section className="glass panel form-stack"><SectionTitle title="成果材料" sub="字段由项目经理定义；队伍老师 / 运营老师后续补充"/><FormField label="材料清单"><textarea rows={4} value={mats.checklist} disabled={!ops} onChange={e=>setMats(m=>({...m,checklist:e.target.value}))} placeholder="研究报告、商业计划书、展示材料…"/></FormField><FormField label="链接 / 存放位置"><textarea rows={3} value={mats.links} disabled={!ops} onChange={e=>setMats(m=>({...m,links:e.target.value}))} placeholder="网盘链接、文档地址…"/></FormField><FormField label="备注"><textarea rows={3} value={mats.notes} disabled={!ops} onChange={e=>setMats(m=>({...m,notes:e.target.value}))} placeholder="提交要求与截止说明"/></FormField>{t.materials?.updated&&<p className="muted">最近由 {t.materials.updatedBy} 更新于 {t.materials.updated}</p>}{ops&&<button type="button" className="primary self-start" onClick={saveMaterials}>保存成果材料</button>}<Notice>真实文件上传将在受控存储接入后开放；当前先用清单与链接登记。</Notice></section>;
  const logTab=<section className="glass panel"><SectionTitle title="运营记录" sub="只读 · 自动记录每一次队伍变更（谁 / 何时 / 什么）"/>{logs.length?logs.map(l=><div className="log-row" key={l.id}><span/><div><p><b>{l.action}</b>{l.detail?` · ${l.detail}`:''}</p><small>{l.byName} · {l.at}</small></div></div>):<EmptyState icon={Clock} title="暂无运营记录" description="队伍创建、阶段设定、进度与材料更新会自动记入此处，不可手动编辑。"/>}</section>;
  return <><Back to="teams"/><div className="glass detail-hero"><ProgramMark program={s.programs.find(p=>p.id===t.program)!}/><div><h1>{t.name}</h1><p>{t.id} · {s.programs.find(p=>p.id===t.program)?.name}</p></div><Badge tone={t.status==='正常进行'?'green':'orange'}>{t.status}</Badge></div><TeamOfferSummary team={t} courses={teamCourses}/>{stageSection}<DetailTabs items={[{name:'队伍成员',content:<TeamRoster team={t}/>},{name:'队伍进度',content:progressTab},{name:'成果材料',content:materialsTab},...(ops?[{name:'运营记录',content:logTab}]:[])]}/></>}
export function CourseRow({id}:{id:string}){const s=useNexus(),c=s.courses.find(x=>x.id===id);if(!c)return null;return <button className="course-row" onClick={()=>s.go('courses/'+id)}><span className="course-time">{c.time.split('–')[0]}<small>{c.date.slice(5)}</small></span><div><h3>{c.name}</h3><p>{s.programs.find(p=>p.id===c.program)?.short} · {s.teams.find(t=>t.id===c.team)?.name} · {c.teacher}</p></div><Badge tone={c.status==='已完成'?'green':'violet'}>{c.status}</Badge><ChevronRight size={17}/></button>}
